import {PUBLIC_DEMO_USERNAME,PUBLIC_DEMO_PASSWORD} from './profile.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const passwordField=(id,label,autocomplete,value='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="password" minlength="8" maxlength="128" autocomplete="${autocomplete}" value="${esc(value)}" required><small>至少8个字符；密码只用于当前浏览器的本机登录。</small></div>`;
export function authPage(mode='login',message='',username=''){
  const register=mode==='register',loginName=username||PUBLIC_DEMO_USERNAME;
  const form=register
    ?`<form id="registerForm"><div class="field"><label for="authUsername">用户名</label><input id="authUsername" name="username" type="text" minlength="2" maxlength="20" autocomplete="username" required><small>2—20位中文、字母、数字、下划线或短横线；新账号从空白数据开始。</small></div>${passwordField('authPassword','设置密码','new-password')}${passwordField('authConfirmPassword','确认密码','new-password')}<button class="primary auth-submit" type="submit">创建本机账号并进入</button><button class="auth-secondary" type="button" data-auth-mode="login">返回登录</button></form>`
    :`<form id="loginForm"><div class="field"><label for="authUsername">用户名</label><input id="authUsername" name="username" type="text" maxlength="20" autocomplete="username" value="${esc(loginName)}" required></div>${passwordField('authPassword','密码','current-password',loginName===PUBLIC_DEMO_USERNAME?PUBLIC_DEMO_PASSWORD:'')}<button class="primary auth-submit" type="submit">登录</button><button class="auth-secondary" type="button" data-auth-mode="register">创建自己的空白账号</button></form>`;
  return `<main class="auth-shell"><section class="auth-card"><div class="auth-brand"><div class="brandicon">≈</div><div><strong>薪有数</strong><small>个人收入与个税规划</small></div></div><div class="auth-copy"><span class="eyebrow">本机账号</span><h1>${register?'创建你的访问账号':'欢迎回来'}</h1><p>${register?'设置一个只在当前浏览器生效的用户名和密码，新账号进入后是待填写的空白数据。':'默认演示账号已经填好虚构案例；也可以创建自己的本机账号，从空白数据开始。'}</p></div>${message?`<div class="auth-message">${esc(message)}</div>`:''}${form}<div class="auth-local"><b>账号数据彼此隔离</b><p>演示账号在不同设备上都加载同一套公开虚构案例；其他账号和工资记录只保存在当前浏览器，不上传服务器，也不支持跨设备同步。请定期导出备份。</p></div></section><aside class="auth-side"><span>PRIVATE INCOME WORKSPACE</span><h2>把收入、税负与规划，<br>放进一个清晰视图。</h2><ul><li>默认演示账号开箱即可查看完整案例</li><li>自建账号从空白数据开始，彼此独立</li><li>任何设备获得链接后都可以使用</li></ul></aside></main>`;
}
